INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000295',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss the rule of law at B2","Use Rechtsstaat vocabulary","Talk about German constitutional democracy and democratic principles"],"explanation":{"intro":"Rule of law and democracy vocabulary covers democratic institutions, separation of powers, and constitutional principles at B2.","culturalNote":"Rechtsstaat: German constitutional democracy is built on the Grundgesetz (Basic Law — 1949). Key principles: Rechtsstaatsprinzip (rule of law), Demokratieprinzip (democracy principle), Sozialstaatsprinzip (welfare state principle), Bundesstaatsprinzip (federalism), Gewaltenteilung (separation of powers). Ewigkeitsklausel (eternity clause — Art. 79 III GG — cannot be changed: dignity, federalism, democratic principles). Bundesverfassungsgericht (Federal Constitutional Court — Karlsruhe — most respected institution in Germany). Grundrechte (fundamental rights — Art. 1-19). Wehrhafter Demokratie (militant democracy — can ban anti-constitutional parties — Art. 21 II GG, NPD ban attempts). Gedanke: democracy must defend itself against its own destruction."},"examples":[{"german":"Der Rechtsstaat beruht nicht allein auf der Legalität staatlicher Handlungen, sondern auf deren Legitimität: Gesetze müssen inhaltlich gerechten Mindeststandards entsprechen, da formale Korrektheit allein keinen Schutz vor Willkür bietet.","english":"The rule of law rests not solely on the legality of state actions, but on their legitimacy: laws must correspond to substantively just minimum standards, since formal correctness alone provides no protection against arbitrariness."},{"german":"Die streitbare Demokratie als Konzept beruht auf der historischen Erkenntnis, dass demokratische Systeme ihre eigene Abschaffung über demokratische Verfahren ermöglichen können — eine Lehre, die Deutschland nach 1945 in seine Verfassungsordnung eingeschrieben hat.","english":"Militant democracy as a concept rests on the historical insight that democratic systems can enable their own abolition through democratic procedures — a lesson that Germany inscribed into its constitutional order after 1945."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss the rule of law, Germany''s Basic Law, and militant democracy at B2."}}',
'{"items":[{"word":"beruhen auf","translation":"to rest on/be based on","pronunciation":"beh-ROO-en owf","example":"Auf Legitimität beruhen."},{"word":"die Willkür","translation":"arbitrariness","pronunciation":"dee VIL-kür","example":"Schutz vor Willkür."},{"word":"inhaltlich","translation":"substantively/in terms of content","pronunciation":"IN-halt-likh","example":"Inhaltlich gerecht."},{"word":"die Erkenntnis","translation":"insight/finding","pronunciation":"dee er-KENT-nis","example":"Historische Erkenntnis."},{"word":"einschreiben in","translation":"to inscribe into","pronunciation":"YN-shry-ben in","example":"In die Verfassung einschreiben."},{"word":"die streitbare Demokratie","translation":"militant democracy","pronunciation":"dee SHTRY-tba-reh deh-mo-krah-TEE","example":"Streitbare Demokratie."}]}',
'{"title":"Nicht allein auf X, sondern auf Y beruhen — resting not solely on X but on Y (expanding the basis)","pattern":"etwas beruht nicht allein auf X, sondern auf Y = something rests not solely on X, but on Y (beruhen auf = to rest on/be based on; nicht allein...sondern = not solely...but — expanding scope)","explanation":"Beruhen auf = to rest on, be based on (auf + dative). Nicht allein auf X, sondern auf Y = not solely on X, but (also) on Y (nicht allein = not only/solely — stronger than nicht nur). Der Rechtsstaat beruht nicht allein auf Legalität, sondern auf Legitimität = The rule of law rests not solely on legality but on legitimacy. ''Nicht allein'' vs ''nicht nur'': nicht allein = not solely (often used when a reductive view is being corrected), nicht nur = not only (more neutral expansion). Compare: nicht nur X, sondern auch Y (not only X but also Y), nicht bloß X, sondern Y (not merely X but Y — even stronger reduction being corrected).","examples":[{"sentence":"Vertrauen beruht nicht allein auf Worten, sondern auf Taten.","translation":"Trust rests not solely on words, but on deeds."},{"sentence":"Bildung beruht nicht allein auf Wissen, sondern auf Urteilsvermögen.","translation":"Education rests not solely on knowledge, but on the capacity for judgement."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Willkür'' means?","options":["arbitrariness","injustice","oppression","tyranny"],"correctAnswer":"arbitrariness"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The rule of law rests not solely on the legality of state actions, but on their legitimacy: laws must correspond to substantively just minimum standards, since formal correctness alone provides no protection against arbitrariness.","options":["Der Rechtsstaat beruht nicht allein auf der Legalität staatlicher Handlungen, sondern auf deren Legitimität: Gesetze müssen inhaltlich gerechten Mindeststandards entsprechen, da formale Korrektheit allein keinen Schutz vor Willkür bietet.","Ein Rechtsstaat braucht gerechte Gesetze, nicht nur legale.","Formale Gesetze sind kein Garant für Gerechtigkeit.","Der Rechtsstaat verbindet Legalität mit Legitimität."],"correctAnswer":"Der Rechtsstaat beruht nicht allein auf der Legalität staatlicher Handlungen, sondern auf deren Legitimität: Gesetze müssen inhaltlich gerechten Mindeststandards entsprechen, da formale Korrektheit allein keinen Schutz vor Willkür bietet."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Vertrauen beruht nicht allein auf Worten, sondern auf ___.","options":["Taten","Fakten","Beweisen","Ergebnissen"],"correctAnswer":"Taten"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Education rests not solely on knowledge but on the capacity for judgement","wordBankItems":["Bildung","beruht","nicht","allein","auf","Wissen",",","sondern","auf","Urteilsvermögen","."],"correctAnswer":"Bildung beruht nicht allein auf Wissen , sondern auf Urteilsvermögen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Einschreiben in'' means?","options":["to inscribe into","to write into","to embed in","to encode in"],"correctAnswer":"to inscribe into"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000296',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss federalism at B2","Use Föderalismus vocabulary","Talk about Germany''s federal structure and state-federal relations"],"explanation":{"intro":"Federalism vocabulary covers Germany''s federal structure, state-federal relations, and the Bundesrat at B2.","culturalNote":"Föderalismus: Germany is a federal state (Bundesstaat). 16 Bundesländer (federal states — with own parliaments). Bundesrat (Federal Council — represents state governments — not directly elected — states vote as a bloc). Zustimmungsgesetze (laws requiring Bundesrat approval — ~40%). Kompetenzverteilung (division of competences): ausschließliche Bundeskompetenzen (exclusive federal competences), konkurrierende Kompetenzen (concurrent competences), Kulturhoheit der Länder (state sovereignty over education/culture). Horizontaler Finanzausgleich (horizontal fiscal equalisation — rich states support poor states — controversial). Unitarisierungstendenz (centralisation tendency — federal creep). Bayerischer Verfassungsgerichtshof (Bavarian Constitutional Court)."},"examples":[{"german":"Der deutsche Föderalismus zeichnet sich durch eine eigentümliche Doppelstruktur aus: Die Bundesländer besitzen eigene Gesetzgebungskompetenzen in Kernbereichen wie Schule und Polizei, administrieren zugleich aber den Großteil des Bundesrechts, was zu einer engen Verflechtung führt.","english":"German federalism is characterised by a peculiar dual structure: the federal states possess their own legislative competences in core areas such as school and police, but at the same time administer the bulk of federal law, which leads to close entanglement."},{"german":"Kritiker des deutschen Föderalismus monieren, dass der Trend zur Unitarisierung — die faktische Angleichung der Länder an einheitliche Bundesstandards — die ursprüngliche Idee föderaler Vielfalt und regionaler Identität sukzessive aushöhlt.","english":"Critics of German federalism complain that the trend towards unitarisation — the factual alignment of the states to uniform federal standards — is successively hollowing out the original idea of federal diversity and regional identity."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s federal structure, legislative competences, and state-federal relations at B2."}}',
'{"items":[{"word":"eigentümlich","translation":"peculiar/characteristic","pronunciation":"EYE-gen-tü-mlikh","example":"Eigentümliche Struktur."},{"word":"die Verflechtung","translation":"entanglement/intertwining","pronunciation":"dee fer-FLEKH-toong","example":"Enge Verflechtung."},{"word":"monieren","translation":"to complain/criticise","pronunciation":"mo-NEER-en","example":"Kritiker monieren."},{"word":"die Angleichung","translation":"alignment/equalisation","pronunciation":"dee AN-gly-khoong","example":"Angleichung an Standards."},{"word":"sukzessive","translation":"successively","pronunciation":"zook-tse-SEE-veh","example":"Sukzessive aushöhlen."},{"word":"aushöhlen","translation":"to hollow out","pronunciation":"OWS-hö-len","example":"Idee aushöhlen."}]}',
'{"title":"Sich durch X auszeichnen — to be characterised by X (distinctive feature)","pattern":"etwas zeichnet sich durch X aus = something is characterised by X, something stands out through X (sich auszeichnen durch = to be distinguished by — separable: zeichnet...aus)","explanation":"Sich auszeichnen durch = to be characterised by, to stand out through (separable verb: zeichnet...aus). Der Föderalismus zeichnet sich durch eine Doppelstruktur aus = German federalism is characterised by a dual structure (zeichnet...aus = separable). The subject is distinguished/notable because of X. Compare: sich durch X kennzeichnen (to characterise itself by X — more neutral), geprägt sein durch (to be shaped by — more passive/historical), charakterisiert sein durch (characterised by — more academic/passive). Sich auszeichnen is slightly elevated, often for notable or defining features.","examples":[{"sentence":"Das System zeichnet sich durch seine Flexibilität aus.","translation":"The system is characterised by its flexibility."},{"sentence":"Die Sprache zeichnet sich durch eine reiche Grammatik aus.","translation":"The language is characterised by a rich grammar."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Eigentümlich'' means?","options":["peculiar/characteristic","strange","unique","idiosyncratic"],"correctAnswer":"peculiar/characteristic"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"German federalism is characterised by a peculiar dual structure: the federal states possess their own legislative competences in core areas such as school and police, but at the same time administer the bulk of federal law, which leads to close entanglement.","options":["Der deutsche Föderalismus zeichnet sich durch eine eigentümliche Doppelstruktur aus: Die Bundesländer besitzen eigene Gesetzgebungskompetenzen in Kernbereichen wie Schule und Polizei, administrieren zugleich aber den Großteil des Bundesrechts, was zu einer engen Verflechtung führt.","In Deutschland haben die Bundesländer eigene Gesetze in Bildung und Polizei.","Föderalismus bedeutet, dass Bundesländer und Bund getrennte Aufgaben haben.","Der Föderalismus verbindet Länderautonomie mit Bundeseinheitlichkeit."],"correctAnswer":"Der deutsche Föderalismus zeichnet sich durch eine eigentümliche Doppelstruktur aus: Die Bundesländer besitzen eigene Gesetzgebungskompetenzen in Kernbereichen wie Schule und Polizei, administrieren zugleich aber den Großteil des Bundesrechts, was zu einer engen Verflechtung führt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das System zeichnet sich durch seine Flexibilität ___.","options":["aus","ab","an","auf"],"correctAnswer":"aus"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The language is characterised by a rich grammar","wordBankItems":["Die","Sprache","zeichnet","sich","durch","eine","reiche","Grammatik","aus","."],"correctAnswer":"Die Sprache zeichnet sich durch eine reiche Grammatik aus ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Aushöhlen'' means?","options":["to hollow out","to undermine","to erode","to degrade"],"correctAnswer":"to hollow out"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000297',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss constitutional law at B2","Use Verfassungsrecht vocabulary","Talk about fundamental rights, constitutional review, and Germany''s Basic Law"],"explanation":{"intro":"Constitutional law vocabulary covers fundamental rights, constitutional review, and the structure of Germany''s Basic Law at B2.","culturalNote":"Verfassungsrecht: Grundgesetz (Basic Law — 1949 — originally provisional, now permanent). Grundrechte (fundamental rights — Title I, Art. 1-19): Menschenwürde (human dignity — Art. 1 — most protected — absolute), Allgemeines Persönlichkeitsrecht (general personality right — Art. 2), Gleichheitssatz (equality clause — Art. 3). Verfassungsbeschwerde (constitutional complaint — individual citizens can petition BVerfG — rare: ~95% rejected). Normenkontrolle (constitutional review): abstrakte (abstract — from state actors), konkrete (concrete — from courts). BVerfG decisions: Lüth-Urteil (1958 — constitution radiates into private law), Volkszählungsurteil (1983 — informational self-determination), Solange-Entscheidung (EU law/sovereignty)."},"examples":[{"german":"Die Grundrechte des Grundgesetzes entfalten nach der Lüth-Entscheidung des Bundesverfassungsgerichts eine mittelbare Drittwirkung: Sie strahlen als objektive Werteordnung in das Privatrecht aus und verpflichten nicht nur den Staat, sondern prägen auch Auslegung und Anwendung privater Rechtsverhältnisse.","english":"The fundamental rights of the Basic Law, following the Lüth decision of the Federal Constitutional Court, unfold an indirect third-party effect: they radiate as an objective value order into private law and oblige not only the state, but also shape the interpretation and application of private legal relationships."},{"german":"Die Verfassungsbeschwerde ist das letzte innerstaatliche Rechtsmittel: Wer alle Instanzen durchlaufen hat und noch immer die Verletzung eines Grundrechts rügt, kann das Bundesverfassungsgericht anrufen — ein Ausdruck der Idee, dass jede Rechtsordnung eine letzte Wächterfunktion braucht.","english":"The constitutional complaint is the final domestic legal remedy: whoever has gone through all instances and still complains of the violation of a fundamental right can call on the Federal Constitutional Court — an expression of the idea that every legal order needs a final guardian function."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s Basic Law, fundamental rights, and constitutional review at B2."}}',
'{"items":[{"word":"entfalten","translation":"to unfold/develop","pronunciation":"ent-FAL-ten","example":"Wirkung entfalten."},{"word":"die Drittwirkung","translation":"third-party effect","pronunciation":"dee DRIT-vir-koong","example":"Mittelbare Drittwirkung."},{"word":"ausstrahlen","translation":"to radiate/emit","pronunciation":"OWS-shtrah-len","example":"In Privatrecht ausstrahlen."},{"word":"rügen","translation":"to complain of/censure","pronunciation":"RÜ-gen","example":"Grundrechtsverletzung rügen."},{"word":"anrufen","translation":"to call on/petition","pronunciation":"AN-roo-fen","example":"Gericht anrufen."},{"word":"die Wächterfunktion","translation":"guardian function","pronunciation":"dee VEKH-ter-foonk-tsyohn","example":"Letzte Wächterfunktion."}]}',
'{"title":"In X ausstrahlen — to radiate into X (sphere of influence)","pattern":"etwas strahlt in X aus = something radiates into X (ausstrahlen = separable verb: strahlt...aus; in + accusative marks where the radiation reaches)","explanation":"Ausstrahlen in = to radiate into (separable: strahlt...aus). Die Grundrechte strahlen in das Privatrecht aus = The fundamental rights radiate into private law. The metaphor is of light or energy spreading into a domain — used in German constitutional law (Ausstrahlungswirkung = radiating effect) to describe how public law norms influence private law. Not the same as ''applying to'' (gelten für) — it suggests permeation and influence on interpretation. Compare: sich erstrecken auf (to extend to — more direct coverage), wirken auf (to act on — more general effect), prägen (to shape — more formative), durchdringen (to permeate — stronger/more complete).","examples":[{"sentence":"Die neuen Grundsätze strahlen in alle Rechtsbereiche aus.","translation":"The new principles radiate into all areas of law."},{"sentence":"Sein Einfluss strahlt weit über die Wissenschaft aus.","translation":"His influence radiates far beyond academia."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Drittwirkung'' means?","options":["third-party effect","indirect effect","horizontal effect","radiating effect"],"correctAnswer":"third-party effect"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The fundamental rights of the Basic Law, following the Lüth decision of the Federal Constitutional Court, unfold an indirect third-party effect: they radiate as an objective value order into private law and oblige not only the state, but also shape the interpretation and application of private legal relationships.","options":["Die Grundrechte des Grundgesetzes entfalten nach der Lüth-Entscheidung des Bundesverfassungsgerichts eine mittelbare Drittwirkung: Sie strahlen als objektive Werteordnung in das Privatrecht aus und verpflichten nicht nur den Staat, sondern prägen auch Auslegung und Anwendung privater Rechtsverhältnisse.","Die Grundrechte binden nur den Staat, wirken aber indirekt auf das Privatrecht.","Das Bundesverfassungsgericht schützt Grundrechte auch im Privatrecht.","Grundrechte gelten nicht nur im öffentlichen Recht, sondern auch privat."],"correctAnswer":"Die Grundrechte des Grundgesetzes entfalten nach der Lüth-Entscheidung des Bundesverfassungsgerichts eine mittelbare Drittwirkung: Sie strahlen als objektive Werteordnung in das Privatrecht aus und verpflichten nicht nur den Staat, sondern prägen auch Auslegung und Anwendung privater Rechtsverhältnisse."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die neuen Grundsätze strahlen in alle Rechtsbereiche ___.","options":["aus","ein","durch","über"],"correctAnswer":"aus"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: His influence radiates far beyond academia","wordBankItems":["Sein","Einfluss","strahlt","weit","über","die","Wissenschaft","aus","."],"correctAnswer":"Sein Einfluss strahlt weit über die Wissenschaft aus ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Rügen'' means?","options":["to complain of/censure","to challenge","to claim","to allege"],"correctAnswer":"to complain of/censure"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000298',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss the European Union at B2","Use EU vocabulary","Talk about European integration, EU institutions, and Germany''s role in Europe"],"explanation":{"intro":"European Union vocabulary covers EU institutions, integration, and the debate about European sovereignty at B2.","culturalNote":"Europäische Union: Founded via Schuman Declaration (1950), Treaty of Rome (1957 — EWG), Maastricht (1992 — EU), Lisbon (2007). Key institutions: Europäischer Rat (heads of government), Rat der EU (ministers — legislative), Europäisches Parlament (MEPs — directly elected), Europäische Kommission (executive — proposals), EuGH (Court of Justice). Eurozone: 20 members. Key debates: Souveränitätsabgabe (transfer of sovereignty — Art. 23 GG — German BVerfG Solange and Lissabon decisions), Brexit (UK 2020 — cautionary tale?), Erweiterung (enlargement), Demokratiedefizit (democracy deficit), Subsidiarität (subsidiarity). Germany: largest economy, net contributor, central to EU stability but often cautious on integration deepening."},"examples":[{"german":"Die europäische Integration ist ein Projekt, das nationale Souveränitäten nicht beseitigt, sondern in einem Mehrebenensystem supranational verdichtet: Die Mitgliedstaaten übertragen Kompetenzen an Organe, die verbindliche Rechtsakte erlassen, die unmittelbar im nationalen Rechtsraum gelten.","english":"European integration is a project that does not eliminate national sovereignties, but densifies them supranationally in a multi-level system: member states transfer competences to bodies that issue binding legal acts which apply directly in the national legal space."},{"german":"Das viel beklagte Demokratiedefizit der EU spiegelt einen realen Spannungsbogen wider: Das Europäische Parlament hat zwar erhebliche Mitentscheidungsrechte erhalten, aber die exekutivlastige Machtbalance und geringe Bekanntheit europäischer Politik behindern eine substanzielle Bürgerinnen- und Bürgerbeteiligung.","english":"The much-lamented democracy deficit of the EU reflects a real arc of tension: the European Parliament has indeed received considerable co-decision rights, but the executive-heavy balance of power and low familiarity with European politics impede substantial citizens'' participation."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss European integration, EU institutions, and the democracy deficit at B2."}}',
'{"items":[{"word":"beseitigen","translation":"to eliminate","pronunciation":"beh-ZY-ti-gen","example":"Souveränität beseitigen."},{"word":"verdichten","translation":"to densify/compress","pronunciation":"fer-DIKHTЕН","example":"Supranational verdichten."},{"word":"verbindlich","translation":"binding","pronunciation":"fer-BIND-likh","example":"Verbindliche Rechtsakte."},{"word":"unmittelbar","translation":"directly","pronunciation":"oon-MIT-el-bahr","example":"Unmittelbar gelten."},{"word":"exekutivlastig","translation":"executive-heavy","pronunciation":"eg-ZEK-oo-teef-las-tikh","example":"Exekutivlastige Machtbalance."},{"word":"behindern","translation":"to impede","pronunciation":"beh-HIN-dern","example":"Beteiligung behindern."}]}',
'{"title":"Nicht X, sondern in Y verdichten — densifying rather than eliminating (structural transformation)","pattern":"etwas verdichtet X in Y = something densifies X in Y (verdichten = to densify/compress — used for what happens to sovereignty in EU integration: not eliminated but transformed/concentrated at higher level)","explanation":"Verdichten = to densify, compress, condense. Supranational verdichten = to densify supranationally. Die Integration verdichtet Souveränitäten supranational = Integration densifies (transforms/concentrates) sovereignties supranationally. Not a high-frequency everyday word, but in academic and political discourse about EU integration, it captures the idea that sovereignty is not simply surrendered but transformed and held at a higher level. The negation structure nicht X, sondern Y verdichten = not eliminate X, but densify/transform it in Y — corrects a common misconception (that EU = loss of sovereignty = elimination).","examples":[{"sentence":"Die Kooperation verdichtet nationale Interessen zu einer gemeinsamen Position.","translation":"Cooperation densifies national interests into a joint position."},{"sentence":"Urbanisierung verdichtet Bevölkerung in wenigen Zentren.","translation":"Urbanisation densifies population in a few centres."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Verbindlich'' means?","options":["binding","mandatory","obligatory","compulsory"],"correctAnswer":"binding"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"European integration is a project that does not eliminate national sovereignties, but densifies them supranationally in a multi-level system: member states transfer competences to bodies that issue binding legal acts which apply directly in the national legal space.","options":["Die europäische Integration ist ein Projekt, das nationale Souveränitäten nicht beseitigt, sondern in einem Mehrebenensystem supranational verdichtet: Die Mitgliedstaaten übertragen Kompetenzen an Organe, die verbindliche Rechtsakte erlassen, die unmittelbar im nationalen Rechtsraum gelten.","Die EU beseitigt nationale Souveränitäten durch verbindliche europäische Rechtsakte.","Europäische Integration bedeutet, nationale Kompetenzen an die EU zu übertragen.","Die EU schafft ein Mehrebenensystem, das nationale und supranationale Ebenen verbindet."],"correctAnswer":"Die europäische Integration ist ein Projekt, das nationale Souveränitäten nicht beseitigt, sondern in einem Mehrebenensystem supranational verdichtet: Die Mitgliedstaaten übertragen Kompetenzen an Organe, die verbindliche Rechtsakte erlassen, die unmittelbar im nationalen Rechtsraum gelten."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Kooperation verdichtet nationale Interessen zu einer gemeinsamen ___.","options":["Position","Strategie","Linie","Haltung"],"correctAnswer":"Position"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Urbanisation densifies population in a few centres","wordBankItems":["Urbanisierung","verdichtet","Bevölkerung","in","wenigen","Zentren","."],"correctAnswer":"Urbanisierung verdichtet Bevölkerung in wenigen Zentren ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Behindern'' means?","options":["to impede","to obstruct","to hinder","to prevent"],"correctAnswer":"to impede"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000299',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss international relations at B2","Use Internationale Beziehungen vocabulary","Talk about multilateralism, geopolitics, and international law"],"explanation":{"intro":"International relations vocabulary covers multilateralism, geopolitics, and Germany''s foreign policy role at B2.","culturalNote":"Internationale Beziehungen: Germany: Zivilmacht (civilian power — prioritises diplomacy, multilateralism, EU/NATO). Zeitenwende (2022 — Scholz — fundamental shift after Ukraine invasion: rearmament, €100bn Sondervermögen for Bundeswehr, changing Germany''s pacifist-leaning foreign policy DNA). Key frameworks: NATO (Germany joined 1955), UN Security Council (Germany non-permanent member repeatedly — aspires to permanent seat), OSCE, WTO. Key thinkers: Mearsheimer (offensive realism), Keohane/Nye (liberal institutionalism), Morgenthau (classical realism). German foreign policy tradition: Wandel durch Handel (change through trade — criticism since 2022 — dependency trap with Russia/China). Multilateralismus (Germany''s preferred framework)."},"examples":[{"german":"Die Zeitenwende markiert eine Zäsur in der deutschen Außenpolitik: Die jahrzehntelange Überzeugung, dass wirtschaftliche Verflechtung politischen Wandel befördere — verkörpert in der Formel ''Wandel durch Handel'' — wurde durch den russischen Überfall auf die Ukraine als strategische Fehlkalkulation entlarvt.","english":"The Zeitenwende marks a caesura in German foreign policy: the decades-long conviction that economic entanglement promotes political change — embodied in the formula ''Wandel durch Handel'' — was exposed as a strategic miscalculation by the Russian attack on Ukraine."},{"german":"Multilateralismus als Grundprinzip deutscher Außenpolitik basiert auf der Überzeugung, dass globale Herausforderungen nur durch institutionalisierte Kooperation und geteilte Regelwerke zu bewältigen sind — ein Ansatz, der in einer Welt wachsender Großmachtrivalitäten zunehmend unter Druck gerät.","english":"Multilateralism as a foundational principle of German foreign policy is based on the conviction that global challenges can only be managed through institutionalised cooperation and shared rule frameworks — an approach that is increasingly under pressure in a world of growing great-power rivalries."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s Zeitenwende, multilateralism, and international relations at B2."}}',
'{"items":[{"word":"die Zäsur","translation":"caesura/rupture","pronunciation":"dee tsä-ZOOR","example":"Historische Zäsur."},{"word":"verkörpern","translation":"to embody","pronunciation":"fer-KÖR-pern","example":"In Formel verkörpert."},{"word":"entlarven","translation":"to expose/unmask","pronunciation":"ent-LAR-fen","example":"Als Fehler entlarven."},{"word":"die Fehlkalkulation","translation":"miscalculation","pronunciation":"dee FAYL-kal-koo-lah-tsyohn","example":"Strategische Fehlkalkulation."},{"word":"bewältigen","translation":"to manage/cope with","pronunciation":"beh-VÄL-ti-gen","example":"Herausforderungen bewältigen."},{"word":"das Regelwerk","translation":"rule framework","pronunciation":"dahs RAY-gel-verk","example":"Geteilte Regelwerke."}]}',
'{"title":"Als X entlarvt werden — to be exposed as X (unmasking a false claim)","pattern":"etwas/jemand wird als X entlarvt = something/someone is exposed/unmasked as X (entlarven = to expose, to unmask — past participle: entlarvt; als X marks what was really the case, hidden before)","explanation":"Als X entlarvt werden = to be exposed as X (passive of entlarven = to unmask, expose). Die Überzeugung wurde als Fehlkalkulation entlarvt = The conviction was exposed as a miscalculation. Entlarven implies that something presented itself as something else (virtue, wisdom, good policy) but was revealed to be X (mistake, hypocrisy, miscalculation). Stronger than ''shown to be'' — carries a sense of unmasking after deception or self-deception. Compare: sich als X herausstellen (to turn out to be X — more neutral), als X erwiesen werden (to be proved to be X — more evidentiary), als X identifiziert werden (to be identified as X — neutral labelling).","examples":[{"sentence":"Seine Versprechen wurden als leere Rhetorik entlarvt.","translation":"His promises were exposed as empty rhetoric."},{"sentence":"Der Plan wurde als unrealistisch entlarvt.","translation":"The plan was exposed as unrealistic."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Zäsur'' means?","options":["caesura/rupture","break","turning point","watershed"],"correctAnswer":"caesura/rupture"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The Zeitenwende marks a caesura in German foreign policy: the decades-long conviction that economic entanglement promotes political change — embodied in the formula ''Wandel durch Handel'' — was exposed as a strategic miscalculation by the Russian attack on Ukraine.","options":["Die Zeitenwende markiert eine Zäsur in der deutschen Außenpolitik: Die jahrzehntelange Überzeugung, dass wirtschaftliche Verflechtung politischen Wandel befördere — verkörpert in der Formel ''Wandel durch Handel'' — wurde durch den russischen Überfall auf die Ukraine als strategische Fehlkalkulation entlarvt.","Die Ukraine-Krise hat die deutsche Außenpolitik fundamental verändert.","Wandel durch Handel hat versagt: Russlands Angriff auf die Ukraine war ein Schock.","Deutschland musste seine außenpolitischen Grundüberzeugungen überdenken."],"correctAnswer":"Die Zeitenwende markiert eine Zäsur in der deutschen Außenpolitik: Die jahrzehntelange Überzeugung, dass wirtschaftliche Verflechtung politischen Wandel befördere — verkörpert in der Formel ''Wandel durch Handel'' — wurde durch den russischen Überfall auf die Ukraine als strategische Fehlkalkulation entlarvt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Seine Versprechen wurden als leere Rhetorik ___.","options":["entlarvt","enthüllt","aufgedeckt","demaskiert"],"correctAnswer":"entlarvt"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The plan was exposed as unrealistic","wordBankItems":["Der","Plan","wurde","als","unrealistisch","entlarvt","."],"correctAnswer":"Der Plan wurde als unrealistisch entlarvt ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Bewältigen'' means?","options":["to manage/cope with","to overcome","to handle","to address"],"correctAnswer":"to manage/cope with"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000029a',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss human rights at B2","Use Menschenrechte vocabulary","Talk about international human rights law, universal standards, and debates"],"explanation":{"intro":"Human rights vocabulary covers international human rights law, UN conventions, and debates about universality vs. cultural relativism at B2.","culturalNote":"Menschenrechte: UN Universal Declaration of Human Rights (UDHR — 1948). International Covenant on Civil and Political Rights (ICCPR — 1966), International Covenant on Economic, Social and Cultural Rights (ICESCR — 1966). ECHR: European Convention on Human Rights (EMRK — Council of Europe — 47 members — ECHR court in Strasbourg — not EU). Germany: strong human rights tradition (post-WWII). Key debates: Universalismus vs. Kulturrelativismus (universalism vs. cultural relativism — Asian values debate), Schutzverantwortung (R2P — Responsibility to Protect), Straflosigkeit (impunity), ICC (Internationaler Strafgerichtshof — Den Haag). Human rights as soft power — but selective enforcement undermines credibility."},"examples":[{"german":"Menschenrechte erheben einen universellen Geltungsanspruch — sie sollen nicht von kulturellen Traditionen oder staatlicher Souveränität abhängen. Doch der Einwand des Kulturrelativismus ist nicht einfach abzutun: Er stellt nicht den Wert von Würde und Freiheit infrage, sondern die westliche Deutungshoheit darüber, was diese Werte konkret bedeuten.","english":"Human rights raise a universal claim to validity — they are not supposed to depend on cultural traditions or state sovereignty. But the objection of cultural relativism is not simply to be dismissed: it does not question the value of dignity and freedom, but the Western interpretive authority over what these values concretely mean."},{"german":"Die selektive Durchsetzung von Menschenrechten untergräbt ihre normative Kraft: Wenn Staaten, die selbst gegen Menschenrechte verstoßen, als Anwälte für ihre Durchsetzung auftreten, erodiert die Glaubwürdigkeit des gesamten internationalen Menschenrechtssystems.","english":"The selective enforcement of human rights undermines their normative power: when states that themselves violate human rights appear as advocates for their enforcement, the credibility of the entire international human rights system erodes."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss human rights universalism, cultural relativism, and selective enforcement at B2."}}',
'{"items":[{"word":"der Geltungsanspruch","translation":"claim to validity","pronunciation":"dayr GEL-toonks-an-shprookh","example":"Universeller Geltungsanspruch."},{"word":"abtun","translation":"to dismiss","pronunciation":"AP-toon","example":"Nicht abzutun."},{"word":"die Deutungshoheit","translation":"interpretive authority","pronunciation":"dee DOY-toonks-hoh-hyt","example":"Westliche Deutungshoheit."},{"word":"verstoßen gegen","translation":"to violate","pronunciation":"fer-SHTOS-sen GAY-gen","example":"Gegen Menschenrechte verstoßen."},{"word":"auftreten als","translation":"to appear as/act as","pronunciation":"OWF-tray-ten als","example":"Als Anwalt auftreten."},{"word":"erodieren","translation":"to erode","pronunciation":"eh-ro-DEER-en","example":"Glaubwürdigkeit erodiert."}]}',
'{"title":"Nicht X infrage stellen, sondern Y — questioning not X but Y (precise target of critique)","pattern":"etwas stellt nicht X infrage, sondern Y = something does not question X, but Y (stellen + infrage/in Frage = to question; nicht X, sondern Y = precise correction of what is being questioned)","explanation":"Infrage stellen = to call into question, to question (infrage or in Frage — both acceptable). Nicht X infrage stellen, sondern Y = to not question X, but Y (corrective structure: clarifies the precise target of critique). Der Einwand stellt nicht den Wert der Würde infrage, sondern die Deutungshoheit darüber = The objection does not question the value of dignity, but the interpretive authority over it. This pattern is precision-repair: it corrects a too-broad reading of a critique by specifying exactly what is and is not being questioned. Compare: nicht anzweifeln, sondern hinterfragen (not to doubt, but to scrutinise — more specific action), nicht bestreiten, sondern relativieren (not to deny, but to relativise).","examples":[{"sentence":"Der Artikel stellt nicht die Methode infrage, sondern die Schlussfolgerung.","translation":"The article does not question the method, but the conclusion."},{"sentence":"Ich stelle nicht deinen Einsatz infrage, sondern den Zeitplan.","translation":"I do not question your commitment, but the timeline."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Geltungsanspruch'' means?","options":["claim to validity","normative authority","universal applicability","legitimacy claim"],"correctAnswer":"claim to validity"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Human rights raise a universal claim to validity — they are not supposed to depend on cultural traditions or state sovereignty. But the objection of cultural relativism is not simply to be dismissed: it does not question the value of dignity and freedom, but the Western interpretive authority over what these values concretely mean.","options":["Menschenrechte erheben einen universellen Geltungsanspruch — sie sollen nicht von kulturellen Traditionen oder staatlicher Souveränität abhängen. Doch der Einwand des Kulturrelativismus ist nicht einfach abzutun: Er stellt nicht den Wert von Würde und Freiheit infrage, sondern die westliche Deutungshoheit darüber, was diese Werte konkret bedeuten.","Menschenrechte sind universell, aber Kulturrelativismus stellt sie zu Recht infrage.","Kulturrelativismus kritisiert die westliche Dominanz bei der Definition von Menschenrechten.","Menschenrechte gelten universal, aber ihre Auslegung ist kulturell umstritten."],"correctAnswer":"Menschenrechte erheben einen universellen Geltungsanspruch — sie sollen nicht von kulturellen Traditionen oder staatlicher Souveränität abhängen. Doch der Einwand des Kulturrelativismus ist nicht einfach abzutun: Er stellt nicht den Wert von Würde und Freiheit infrage, sondern die westliche Deutungshoheit darüber, was diese Werte konkret bedeuten."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der Artikel stellt nicht die Methode infrage, sondern die ___.","options":["Schlussfolgerung","Ergebnisse","Daten","Analyse"],"correctAnswer":"Schlussfolgerung"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I do not question your commitment but the timeline","wordBankItems":["Ich","stelle","nicht","deinen","Einsatz","infrage",",","sondern","den","Zeitplan","."],"correctAnswer":"Ich stelle nicht deinen Einsatz infrage , sondern den Zeitplan ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Auftreten als'' means?","options":["to appear as/act as","to present as","to step up as","to emerge as"],"correctAnswer":"to appear as/act as"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000029b',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss globalisation at B2","Use Globalisierung vocabulary","Talk about globalisation''s winners and losers, and anti-globalisation movements"],"explanation":{"intro":"Globalisation vocabulary covers economic integration, global inequality, and globalisation backlash at B2.","culturalNote":"Globalisierung: First wave: late 19th century (reversed by WWI). Second wave: post-1945 (Bretton Woods — IMF, World Bank, GATT/WTO). Germany: Exportweltmeister (export world champion — €1.5+ trillion exports p.a.) — highly globalisation-dependent. Key indices: KOF Globalisation Index. Winners/losers: the ''elephant curve'' (Milanovic) shows emerging middle class + global top 1% gain; working class in rich countries loses. Deglobalization tendencies: COVID supply chains, US-China trade war, Reshoring (back-shoring — moving production home). Key critics: Naomi Klein (No Logo), Joseph Stiglitz (Globalization and its Discontents). Germany: Schröder''s Agenda 2010 (adapted Germany to globalisation)."},"examples":[{"german":"Globalisierung ist kein Schicksal, das gleichmäßig über alle hereinbricht, sondern ein Prozess mit klarer Verteilungsdynamik: Sie schafft Wohlstandszuwächse auf aggregierter Ebene, verteilt diese aber ungleich — in einer Weise, die binnenstaatliche Ungleichheiten verschärft und Globalisierungsverlierer in politische Opposition treibt.","english":"Globalisation is not a fate that descends uniformly over everyone, but a process with a clear distribution dynamic: it creates welfare gains at the aggregate level, but distributes these unequally — in a way that sharpens domestic inequalities and drives globalisation losers into political opposition."},{"german":"Die Deglobalisierungstendenzen der 2020er Jahre zeigen, dass wirtschaftliche Integration reversibel ist: Handelskriege, Pandemieunterbrechungen von Lieferketten und geopolitische Blockbildungen erzwingen ein Umdenken bei Unternehmen, die auf maximale Effizienz durch globale Arbeitsteilung gesetzt hatten.","english":"The de-globalisation tendencies of the 2020s show that economic integration is reversible: trade wars, pandemic disruptions of supply chains, and geopolitical bloc formation force a rethink at companies that had bet on maximum efficiency through global division of labour."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss globalisation winners and losers, de-globalisation, and Germany''s export dependence at B2."}}',
'{"items":[{"word":"das Schicksal","translation":"fate","pronunciation":"dahs SHIK-zahl","example":"Kein unausweichliches Schicksal."},{"word":"hereinbrechen","translation":"to descend/break over","pronunciation":"heh-RYN-brekh-en","example":"Über alle hereinbrechen."},{"word":"aggregiert","translation":"aggregated","pronunciation":"ag-reh-GEERT","example":"Auf aggregierter Ebene."},{"word":"erzwingen","translation":"to force/compel","pronunciation":"er-TSVING-en","example":"Umdenken erzwingen."},{"word":"reversibel","translation":"reversible","pronunciation":"reh-ver-ZEE-bel","example":"Reversibel sein."},{"word":"die Blockbildung","translation":"bloc formation","pronunciation":"dee BLOK-bil-doong","example":"Geopolitische Blockbildung."}]}',
'{"title":"In politische Opposition treiben — to drive into political opposition (forced outcome)","pattern":"jemanden/etwas in X treiben = to drive someone/something into X (treiben = to drive — here: the subject drives the object into a state or position; accusative marks the destination-state)","explanation":"In X treiben = to drive into X (treiben = to drive, push — here used for social/political forces pushing people into a state). Globalisierung treibt Verlierer in politische Opposition = Globalisation drives losers into political opposition (in + accusative = into; the accusative marks the destination or resulting state). The verb treiben adds agency and forcefulness — not just ''arriving at'' opposition but being pushed there by an external force. Compare: in X zwingen (to force into X — even stronger compulsion), in X drängen (to push/pressure into X — less violent), in X führen (to lead into X — more neutral directionality), in X bringen (to bring into X — least forceful).","examples":[{"sentence":"Die Krise trieb viele in die Armut.","translation":"The crisis drove many into poverty."},{"sentence":"Der Druck treibt Länder in Abhängigkeit.","translation":"The pressure drives countries into dependency."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Reversibel'' means?","options":["reversible","undoable","changeable","temporary"],"correctAnswer":"reversible"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Globalisation is not a fate that descends uniformly over everyone, but a process with a clear distribution dynamic: it creates welfare gains at the aggregate level, but distributes these unequally — in a way that sharpens domestic inequalities and drives globalisation losers into political opposition.","options":["Globalisierung ist kein Schicksal, das gleichmäßig über alle hereinbricht, sondern ein Prozess mit klarer Verteilungsdynamik: Sie schafft Wohlstandszuwächse auf aggregierter Ebene, verteilt diese aber ungleich — in einer Weise, die binnenstaatliche Ungleichheiten verschärft und Globalisierungsverlierer in politische Opposition treibt.","Globalisierung schafft Gewinner und Verlierer, was zu politischer Polarisierung führt.","Die Gewinne aus Globalisierung sind ungleich verteilt und gefährden den sozialen Zusammenhalt.","Globalisierungsverlierer werden politisch radikaler, wenn sie sich abgehängt fühlen."],"correctAnswer":"Globalisierung ist kein Schicksal, das gleichmäßig über alle hereinbricht, sondern ein Prozess mit klarer Verteilungsdynamik: Sie schafft Wohlstandszuwächse auf aggregierter Ebene, verteilt diese aber ungleich — in einer Weise, die binnenstaatliche Ungleichheiten verschärft und Globalisierungsverlierer in politische Opposition treibt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Krise trieb viele in die ___.","options":["Armut","Not","Krise","Verzweiflung"],"correctAnswer":"Armut"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The pressure drives countries into dependency","wordBankItems":["Der","Druck","treibt","Länder","in","Abhängigkeit","."],"correctAnswer":"Der Druck treibt Länder in Abhängigkeit ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Erzwingen'' means?","options":["to force/compel","to enforce","to demand","to require"],"correctAnswer":"to force/compel"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000029c',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss development policy at B2","Use Entwicklungspolitik vocabulary","Talk about aid effectiveness, ODA, and Germany''s development cooperation"],"explanation":{"intro":"Development policy vocabulary covers official development assistance, aid effectiveness, and Germany''s role in development cooperation at B2.","culturalNote":"Entwicklungspolitik: Germany: third-largest ODA (Official Development Assistance) donor. Key ministry: BMZ (Bundesministerium für wirtschaftliche Zusammenarbeit und Entwicklung). Key agencies: GIZ (Deutsche Gesellschaft für Internationale Zusammenarbeit — technical assistance), KfW Entwicklungsbank. Germany: 0.73% ODA/GNI (above 0.7% UN target). Key debates: Wirksamkeit der Hilfe (aid effectiveness — Dambisa Moyo ''Dead Aid''), Konditionalisierung (conditionality), Ownership-Prinzip (recipient ownership), Do-No-Harm. SDG 17: Partnerships. Key concepts: Strukturwandel (structural change — diversification beyond raw materials), Finanzialisierung (financialisation), Neoliberale Strukturanpassung (SAPs — 1980s-90s critique). China: Belt and Road Initiative as alternative."},"examples":[{"german":"Entwicklungspolitik steht vor einem konzeptuellen Dilemma: Wenn externe Akteure Gesellschaften nach ihren eigenen Leitbildern verändern wollen, entsteht Abhängigkeit und mangelnde Eigenverantwortung; wenn sie dagegen rein reaktiv auf Eigenbedarfe reagieren, wirken strukturelle Ursachen von Armut und Instabilität fort.","english":"Development policy faces a conceptual dilemma: when external actors want to change societies according to their own guiding models, dependency and insufficient own responsibility arise; when they instead react purely reactively to own needs, structural causes of poverty and instability continue to work."},{"german":"Die Frage, ob Entwicklungshilfe Abhängigkeit erzeugt oder Eigenentwicklung stärkt, kann nicht abstrakt beantwortet werden: Sie hängt von der konkreten Programmgestaltung, dem politischen Kontext des Empfängers und der Bereitschaft externer Akteure ab, Eigeninteressen gegenüber partnerschaftlicher Orientierung zurückzustellen.","english":"The question of whether development aid produces dependency or strengthens self-development cannot be answered abstractly: it depends on the concrete programme design, the political context of the recipient, and the willingness of external actors to put self-interest behind a partnership-oriented orientation."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss aid effectiveness, Germany''s development policy, and the dependency debate at B2."}}',
'{"items":[{"word":"konzeptuell","translation":"conceptual","pronunciation":"kon-tsep-too-EL","example":"Konzeptuelles Dilemma."},{"word":"das Leitbild","translation":"guiding model","pronunciation":"dahs LYT-bild","example":"Eigene Leitbilder."},{"word":"fortw irken","translation":"to continue to work/persist","pronunciation":"FORT-vir-ken","example":"Strukturelle Ursachen wirken fort."},{"word":"die Programmgestaltung","translation":"programme design","pronunciation":"dee pro-GRAM-geh-shtal-toong","example":"Konkrete Programmgestaltung."},{"word":"zurückstellen","translation":"to put behind/subordinate","pronunciation":"tsoo-RÜK-shte-len","example":"Eigeninteressen zurückstellen."},{"word":"partnerschaftlich","translation":"partnership-oriented","pronunciation":"PART-ner-shaft-likh","example":"Partnerschaftliche Orientierung."}]}',
'{"title":"Nicht abstrakt beantwortet werden können — cannot be answered abstractly (context-dependence)","pattern":"etwas kann nicht abstrakt beantwortet werden = something cannot be answered abstractly (abstrakt = abstractly — implies the question requires concrete context; the passive infinitive beantworten + werden cannot holds the key claim)","explanation":"Nicht abstrakt beantwortet werden können = cannot be answered abstractly (modal verb können + passive infinitive: beantwortet werden). The formula signals that a question depends on context and cannot be given a universal answer: Sie hängt von... (it depends on...). Common pattern in nuanced argumentation: first deny that a simple answer is possible, then specify the relevant context variables (hängt von...ab). Hängen von...ab (abhängen von = to depend on — separable: hängt...ab). Compare: nicht pauschal beantwortet werden können (cannot be answered across the board), nicht generell gelten (not apply in general), kontextabhängig sein (to be context-dependent).","examples":[{"sentence":"Diese Frage kann nicht abstrakt beantwortet werden — sie hängt vom Einzelfall ab.","translation":"This question cannot be answered abstractly — it depends on the individual case."},{"sentence":"Ob X richtig ist, lässt sich nicht abstrakt entscheiden.","translation":"Whether X is right cannot be decided abstractly."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Partnerschaftlich'' means?","options":["partnership-oriented","cooperative","collaborative","joint"],"correctAnswer":"partnership-oriented"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The question of whether development aid produces dependency or strengthens self-development cannot be answered abstractly: it depends on the concrete programme design, the political context of the recipient, and the willingness of external actors to put self-interest behind a partnership-oriented orientation.","options":["Die Frage, ob Entwicklungshilfe Abhängigkeit erzeugt oder Eigenentwicklung stärkt, kann nicht abstrakt beantwortet werden: Sie hängt von der konkreten Programmgestaltung, dem politischen Kontext des Empfängers und der Bereitschaft externer Akteure ab, Eigeninteressen gegenüber partnerschaftlicher Orientierung zurückzustellen.","Entwicklungshilfe wirkt nur, wenn sie nicht Abhängigkeit erzeugt, sondern lokale Kapazitäten stärkt.","Ob Entwicklungshilfe hilft oder schadet, hängt von ihrer Umsetzung ab.","Entwicklungspolitik muss Partnerschaft statt Abhängigkeit fördern."],"correctAnswer":"Die Frage, ob Entwicklungshilfe Abhängigkeit erzeugt oder Eigenentwicklung stärkt, kann nicht abstrakt beantwortet werden: Sie hängt von der konkreten Programmgestaltung, dem politischen Kontext des Empfängers und der Bereitschaft externer Akteure ab, Eigeninteressen gegenüber partnerschaftlicher Orientierung zurückzustellen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Diese Frage kann nicht abstrakt beantwortet werden — sie hängt vom Einzelfall ___.","options":["ab","aus","auf","an"],"correctAnswer":"ab"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Whether X is right cannot be decided abstractly","wordBankItems":["Ob","X","richtig","ist",",","lässt","sich","nicht","abstrakt","entscheiden","."],"correctAnswer":"Ob X richtig ist , lässt sich nicht abstrakt entscheiden ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Zurückstellen'' means?","options":["to put behind/subordinate","to push back","to postpone","to deprioritise"],"correctAnswer":"to put behind/subordinate"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000029d',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss security policy at B2","Use Sicherheitspolitik vocabulary","Talk about German security policy, NATO, and the Zeitenwende"],"explanation":{"intro":"Security policy vocabulary covers Germany''s defence policy, NATO obligations, and the Zeitenwende at B2.","culturalNote":"Sicherheitspolitik: Germany: long-standing military restraint (Kultur der Zurückhaltung — culture of restraint — post-WWII). NATO: membership since 1955, 2% GDP defence spending target (long missed — Germany at ~1.5%, now 2%+ post-2022). Bundeswehr: established 1955, Innere Führung (civic virtue leadership). Zeitenwende (2022): €100bn Sondervermögen — special fund — rearmament. Nuclear sharing: German Tornado jets carry US nuclear weapons under NATO''s nuclear sharing arrangement (being replaced by F-35). Key debates: Sicherheitsrat (Germany aspires to permanent UN Security Council seat), Verteidigung vs. out-of-area missions (Afghanistan, Mali, Kosovo). Hybride Kriegsführung (hybrid warfare — disinformation, cyberattacks). Resilienz (resilience — societal resilience to hybrid threats)."},"examples":[{"german":"Die Bundeswehr steht vor einem systemischen Problem: Jahrzehnte des Kaputtsparen haben die Einsatzbereitschaft untergraben, sodass selbst der massive Sondervermögen von 100 Milliarden Euro lediglich einen Teil des aufgelaufenen Ausrüstungsdefizits beheben kann — und das in einem geopolitischen Umfeld, in dem Abschreckung wieder handlungsleitend geworden ist.","english":"The Bundeswehr faces a systemic problem: decades of austerity-driven cuts have undermined operational readiness, so that even the massive special fund of 100 billion euros can only remedy a part of the accumulated equipment deficit — and this in a geopolitical environment in which deterrence has once again become action-guiding."},{"german":"Hybride Kriegsführung stellt das klassische Sicherheitsdenken vor Herausforderungen, weil sie die Grenze zwischen Krieg und Frieden verwischt: Desinformationskampagnen, Cyberangriffe und verdeckte Operationen wirken unterhalb der Schwelle, ab der konventionelle Abwehr greift.","english":"Hybrid warfare poses challenges to classical security thinking because it blurs the boundary between war and peace: disinformation campaigns, cyberattacks, and covert operations function below the threshold from which conventional defence takes effect."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s Bundeswehr, the Zeitenwende, and hybrid warfare at B2."}}',
'{"items":[{"word":"kaputtsparen","translation":"to cut to breaking point","pronunciation":"kah-POOT-shpa-ren","example":"Jahrzehntelanges Kaputtsparen."},{"word":"die Einsatzbereitschaft","translation":"operational readiness","pronunciation":"dee YN-zats-beh-ryt-shaft","example":"Einsatzbereitschaft untergraben."},{"word":"handlungsleitend","translation":"action-guiding","pronunciation":"HAND-loonks-ly-tend","example":"Handlungsleitendes Prinzip."},{"word":"verwischen","translation":"to blur","pronunciation":"fer-VISH-en","example":"Grenzen verwischen."},{"word":"verdeckt","translation":"covert","pronunciation":"fer-DEKT","example":"Verdeckte Operationen."},{"word":"greifen","translation":"to take effect/work","pronunciation":"GRY-fen","example":"Abwehr greift."}]}',
'{"title":"Unterhalb der Schwelle, ab der X greift — below the threshold from which X takes effect","pattern":"etwas wirkt unterhalb der Schwelle, ab der X greift = something operates below the threshold from which X takes effect (ab der = from which — relative pronoun with ab; Schwelle = threshold; greifen = to take effect/bite)","explanation":"Unterhalb der Schwelle = below the threshold. Ab der X greift = from which X takes effect (ab + dative relative pronoun der; greifen = to take effect, to bite, to work). Hybrid warfare operates below the threshold from which conventional defence kicks in — it stays beneath the line that would trigger formal response. Greifen in this context = to take effect, to have its intended effect (nicht greifen = to not work). Compare: an der Grenze von (at the boundary of — spatial metaphor), jenseits der Grenze (beyond the limit), die Schwelle überschreiten (to exceed the threshold — triggering response).","examples":[{"sentence":"Die Maßnahme greift erst ab einem bestimmten Niveau.","translation":"The measure takes effect only from a certain level."},{"sentence":"Unterhalb dieser Schwelle greift das Gesetz nicht.","translation":"Below this threshold, the law does not take effect."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Handlungsleitend'' means?","options":["action-guiding","guiding action","norm-setting","directing behaviour"],"correctAnswer":"action-guiding"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Hybrid warfare poses challenges to classical security thinking because it blurs the boundary between war and peace: disinformation campaigns, cyberattacks, and covert operations function below the threshold from which conventional defence takes effect.","options":["Hybride Kriegsführung stellt das klassische Sicherheitsdenken vor Herausforderungen, weil sie die Grenze zwischen Krieg und Frieden verwischt: Desinformationskampagnen, Cyberangriffe und verdeckte Operationen wirken unterhalb der Schwelle, ab der konventionelle Abwehr greift.","Hybride Kriegsführung nutzt Mittel, die unterhalb der Schwelle eines offiziellen Krieges liegen.","Desinformation und Cyberangriffe sind schwer zu bekämpfen, weil sie kein Casus Belli sind.","Hybride Kriegsführung verwischt die Grenze zwischen Krieg und Frieden."],"correctAnswer":"Hybride Kriegsführung stellt das klassische Sicherheitsdenken vor Herausforderungen, weil sie die Grenze zwischen Krieg und Frieden verwischt: Desinformationskampagnen, Cyberangriffe und verdeckte Operationen wirken unterhalb der Schwelle, ab der konventionelle Abwehr greift."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Unterhalb dieser Schwelle greift das Gesetz ___.","options":["nicht","kaum","wenig","selten"],"correctAnswer":"nicht"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The measure takes effect only from a certain level","wordBankItems":["Die","Maßnahme","greift","erst","ab","einem","bestimmten","Niveau","."],"correctAnswer":"Die Maßnahme greift erst ab einem bestimmten Niveau ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Verwischen'' means?","options":["to blur","to erase","to obscure","to muddy"],"correctAnswer":"to blur"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000029e',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss foreign policy at B2","Use Außenpolitik vocabulary","Talk about German foreign policy traditions, transatlanticism, and Indo-Pacific strategy"],"explanation":{"intro":"Foreign policy vocabulary covers Germany''s foreign policy traditions, transatlanticism, and Indo-Pacific reorientation at B2.","culturalNote":"Außenpolitik: Germany''s foreign policy traditions: Westbindung (Western integration — Adenauer), Ostpolitik (Eastern policy — Willy Brandt — engagement with Eastern Europe/DDR), Multilateralismus (multilateralism), Zivilmacht (civilian power — Hanns Maull). Key relationships: USA (transatlanticism — NATO), France (Élysée Treaty 1963, Aachen Treaty 2019 — Franco-German motor), EU (embedding German power), Russia (Ostpolitik → now deep freeze), China (economic ties → Entkopplungsdebatte — decoupling debate). Indo-Pacific strategy (2020): Germany first state to publish Indo-Pacific guidelines — pivot to Asia. Wertebsierte Außenpolitik (values-based foreign policy — Baerbock — vs. Interessenpolitik). G7, G20 membership. Normenunternehmer (norm entrepreneur — promoting international norms)."},"examples":[{"german":"Deutsche Außenpolitik bewegt sich in einem Spannungsfeld zwischen Normativisierung und Interessenpolitik: Während eine wertebasierte Außenpolitik moralische Glaubwürdigkeit beansprucht und internationale Normen stärkt, kann sie mit wirtschaftlichen Abhängigkeiten und geopolitischen Zwängen kollidieren, die pragmatische Konzessionen erfordern.","english":"German foreign policy moves in a field of tension between normativisation and interest politics: while a values-based foreign policy claims moral credibility and strengthens international norms, it can collide with economic dependencies and geopolitical constraints that require pragmatic concessions."},{"german":"Die Debatte über eine Entkopplung von China zeigt exemplarisch das Dilemma der deutschen Außenpolitik: Wirtschaftliche Verflechtungen schaffen einerseits Kooperationsanreize und Abhängigkeiten, andererseits Risiken strategischer Verwundbarkeit, die aus einer Überexposition gegenüber systemrivalischen Partnern entstehen.","english":"The debate about decoupling from China shows exemplarily the dilemma of German foreign policy: economic entanglements create on the one hand incentives for cooperation and dependencies, on the other hand risks of strategic vulnerability that arise from an overexposure to system-rival partners."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss German foreign policy, the values-interests dilemma, and the China decoupling debate at B2."}}',
'{"items":[{"word":"das Spannungsfeld","translation":"field of tension","pronunciation":"dahs SHPAN-noonks-feld","example":"Im Spannungsfeld."},{"word":"die Normativisierung","translation":"normativisation","pronunciation":"dee nor-ma-ti-vi-ZEER-oong","example":"Normativisierung der Außenpolitik."},{"word":"beanspruchen","translation":"to claim","pronunciation":"beh-AN-shproo-khen","example":"Glaubwürdigkeit beanspruchen."},{"word":"die Verwundbarkeit","translation":"vulnerability","pronunciation":"dee fer-VOONT-bahr-kyt","example":"Strategische Verwundbarkeit."},{"word":"die Überexposition","translation":"overexposure","pronunciation":"dee ü-ber-ex-po-ZI-tsyohn","example":"Überexposition gegenüber China."},{"word":"exemplarisch","translation":"exemplarily","pronunciation":"eg-zem-PLAH-rish","example":"Zeigt exemplarisch."}]}',
'{"title":"Sich in einem Spannungsfeld bewegen — to move in a field of tension","pattern":"etwas/jemand bewegt sich in einem Spannungsfeld zwischen X und Y = something/someone moves in a field of tension between X and Y (Spannungsfeld = field of tension — formed from Spannung (tension) + Feld (field))","explanation":"Spannungsfeld = field of tension (compound: Spannung + Feld). Sich in einem Spannungsfeld bewegen = to move in a field of tension (between two poles). Deutsche Außenpolitik bewegt sich im Spannungsfeld zwischen Normativismus und Interessenpolitik = German foreign policy moves between normativism and interest politics. The metaphor is spatial: the subject navigates a space defined by two poles pulling in opposite directions — unlike a simple either/or, the Spannungsfeld implies ongoing navigation. Compare: zwischen X und Y stehen (to stand between X and Y — more static), X und Y in Einklang bringen (to reconcile X and Y), in einem Dilemma stecken (to be caught in a dilemma — more trapped).","examples":[{"sentence":"Journalisten bewegen sich im Spannungsfeld zwischen Objektivität und Meinungsbildung.","translation":"Journalists move in a field of tension between objectivity and opinion formation."},{"sentence":"Die Politik bewegt sich im Spannungsfeld zwischen Freiheit und Sicherheit.","translation":"Policy moves in a field of tension between freedom and security."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Exemplarisch'' means?","options":["exemplarily","typically","illustratively","paradigmatically"],"correctAnswer":"exemplarily"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"German foreign policy moves in a field of tension between normativisation and interest politics: while a values-based foreign policy claims moral credibility and strengthens international norms, it can collide with economic dependencies and geopolitical constraints that require pragmatic concessions.","options":["Deutsche Außenpolitik bewegt sich in einem Spannungsfeld zwischen Normativisierung und Interessenpolitik: Während eine wertebasierte Außenpolitik moralische Glaubwürdigkeit beansprucht und internationale Normen stärkt, kann sie mit wirtschaftlichen Abhängigkeiten und geopolitischen Zwängen kollidieren, die pragmatische Konzessionen erfordern.","Deutsche Außenpolitik muss zwischen Werten und wirtschaftlichen Interessen abwägen.","Eine wertebasierte Außenpolitik kann mit wirtschaftlichen Interessen in Konflikt geraten.","Deutschland steht vor einem Dilemma zwischen moralischer und interessengeleiteter Außenpolitik."],"correctAnswer":"Deutsche Außenpolitik bewegt sich in einem Spannungsfeld zwischen Normativisierung und Interessenpolitik: Während eine wertebasierte Außenpolitik moralische Glaubwürdigkeit beansprucht und internationale Normen stärkt, kann sie mit wirtschaftlichen Abhängigkeiten und geopolitischen Zwängen kollidieren, die pragmatische Konzessionen erfordern."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Journalisten bewegen sich im Spannungsfeld zwischen Objektivität und ___.","options":["Meinungsbildung","Berichterstattung","Kommentierung","Analyse"],"correctAnswer":"Meinungsbildung"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Policy moves in a field of tension between freedom and security","wordBankItems":["Die","Politik","bewegt","sich","im","Spannungsfeld","zwischen","Freiheit","und","Sicherheit","."],"correctAnswer":"Die Politik bewegt sich im Spannungsfeld zwischen Freiheit und Sicherheit ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Verwundbarkeit'' means?","options":["vulnerability","weakness","susceptibility","fragility"],"correctAnswer":"vulnerability"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

